// Demo 用範例告警：預設走高信心（自動）路徑；
// 改成 alertname: 'UnknownAlert' 可測低信心（人工審核）路徑
return [{ json: {
  alertname: 'HighCPUUsage',
  host: 'prod-node-03',
  severity: 'critical',
  message: 'CPU usage at 97% (threshold: 90%)'
} }];

const a = $json.body?.alertname ? $json.body : $json;
return [{ json: {
  alertname: a.alertname || 'UnknownAlert',
  host: a.host || 'unknown',
  severity: a.severity || 'warning',
  message: a.message || ''
} }];

const alert = $('整理告警').item.json;
const text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const clean = text.replace(/```json\n?|```/g, '').trim();
let parsed = {};
try { parsed = JSON.parse(clean); }
catch (e) { parsed = { severity_assessment: 'Medium', root_cause: 'AI 回應解析失敗', suggested_action: '人工檢查', confidence: 0 }; }
// 防禦性處理：confidence 不是數字一律當 0（走人工）
const confidence = Number.isFinite(Number(parsed.confidence)) ? Number(parsed.confidence) : 0;
return [{ json: {
  ...alert,
  severity_assessment: parsed.severity_assessment || 'Medium',
  root_cause: parsed.root_cause || '',
  suggested_action: parsed.suggested_action || '',
  confidence
} }];

const a = $('解析 + 防禦處理').item.json;
return [{ json: {
  route: 'auto',
  ticket_key: $json.key || $json.ticket?.key,
  confidence: a.confidence,
  assessment: a.severity_assessment
} }];

const a = $('解析 + 防禦處理').item.json;
const t = $('開票 + 人工審核標籤').item.json;
return [{ json: {
  route: 'human_review',
  ticket_key: t.key || t.ticket?.key,
  confidence: a.confidence,
  assessment: a.severity_assessment
} }];
